class Solution {public:
 vector<int> findCoins(vector<int>& numWays){
  int n=numWays.size();vector<long long> dp(n+1);dp[0]=1;vector<int> coins;
  for(int i=1;i<=n;++i){long long want=numWays[i-1];
   if(dp[i]>want||want-dp[i]>1)return {};
   if(dp[i]<want){coins.push_back(i);for(int j=i;j<=n;++j)dp[j]+=dp[j-i];}
  }return coins;
 }
};
